package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoInspectorReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun inspectorActivity():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(title="Styled",grade=VideoGrade(.123f,1.234f,.876f,.111f,-.222f),titleStyle=VideoTitleStyle(2,.061f,true,false))},soundtrack=p.soundtrack)}
 private fun editor(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"inspectorReviewDialog",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState,action:()->Unit):Boolean {val p=get(a,"project")as VideoEditProject;return call(a,"commitInspectorReview",d,r,p,0,p.segments[0],action)as Boolean}
 @Test fun titleStyleOnlyChangesStyleWithOneUndoAndOriginalSettings(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val style=old[0].titleStyle.copy(position=0,light=false);val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r){p.setTitleStyle(0,style)});assertEquals(old[0].copy(titleStyle=style),p.segments[0]);assertSame(music,p.soundtrack);assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(style,p.segments[0].titleStyle)}
 @Test fun colorOnlyChangesChosenChannelsAndKeepsWhiteBalance(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val grade=old[0].grade.copy(exposure=.5f,contrast=1.1f,saturation=1.2f);val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r){p.setGrade(0,grade)});assertEquals(old[0].copy(grade=grade),p.segments[0]);assertEquals(old[0].grade.warmth,p.segments[0].grade.warmth);assertEquals(old[0].grade.tint,p.segments[0].grade.tint);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}
 @Test fun whiteBalanceKeepsExposureContrastAndSaturation(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val grade=old[0].grade.copy(warmth=.5f,tint=-.5f);val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r){p.setGrade(0,grade)});assertEquals(old[0].copy(grade=grade),p.segments[0]);assertEquals(old[0].grade.exposure,p.segments[0].grade.exposure);assertEquals(old[0].grade.contrast,p.segments[0].grade.contrast);assertEquals(old[0].grade.saturation,p.segments[0].grade.saturation);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}
 @Test fun untrackedDismissedOrReplacedDialogCannotMutate(){for(flag in listOf("untracked","dismissed","replaced")){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=editor(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"dismissed"->showing(d,false);else->set(a,"inspectorReviewDialog",dialog())};var calls=0;assertFalse(flag,commit(a,d,r){calls++;p.setGrade(0,VideoGrade())});assertEquals(0,calls);assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceRangeSessionRecoveryAndMusicReject(){for(flag in listOf("pause","generation","source","duration","range","mode","recovery","busy","analysis","music")){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=editor(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"range"->set(a,"selectedClip",1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);else->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};val before=p.segments;var calls=0;assertFalse(flag,commit(a,d,r){calls++});assertEquals(0,calls);assertSame(before,p.segments);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun oldStyleOwnerCannotConsumeNewColorOwnerOrReviveAfterUndo(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=editor(a);val current=editor(a);val r=capture(a);var rejected=0;assertFalse(commit(a,old,r){rejected++});assertEquals(0,rejected);assertSame(current,get(a,"inspectorReviewDialog"));assertTrue(commit(a,current,r){p.setGrade(0,VideoGrade())});assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,current,r){rejected++});assertEquals(0,rejected);assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun modelFailureDoesNotReleaseTheCurrentFormBeforeSuccess(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);try{commit(a,d,r){error("Synthetic failure")};fail("Swallowed failure")}catch(e:java.lang.reflect.InvocationTargetException){assertEquals("Synthetic failure",e.cause?.message)};assertSame(d,get(a,"inspectorReviewDialog"));assertSame(old,p.segments);assertFalse(p.canUndo);assertTrue(commit(a,d,r){p.setGrade(0,VideoGrade())});assertNull(get(a,"inspectorReviewDialog"))}
 @Test fun foreignProjectIndexOrClipCannotUseCurrentOwner(){for(flag in listOf("project","index","clip")){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val d=editor(a);val r=capture(a);val other=VideoEditProject(5000);var calls=0;val action:()->Unit={calls++};assertEquals(false,call(a,"commitInspectorReview",d,r,if(flag=="project")other else p,if(flag=="index")1 else 0,if(flag=="clip")old[0].copy(title="Foreign")else old[0],action));assertEquals(0,calls);assertSame(old,p.segments);assertFalse(p.canUndo);assertNull(get(a,"inspectorReviewDialog"))}}
 @Test fun pausedAnalysingOrRecoveringInspectorEntriesReturnBeforeWidgets(){for(flag in listOf("pause","analysis","recovery")){val a=inspectorActivity();when(flag){"pause"->set(a,"workspaceActive",false);"analysis"->set(a,"analyzing",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"outputFormat");call(a,"titleStyle");call(a,"editColor",false);call(a,"editColor",true);assertNull(get(a,"inspectorReviewDialog"));assertNull(get(a,"captionReviewDialogs"))}}
 @Test fun oldControllerSignaturesAndNewOwnedFactoriesRemainAvailable(){val title=VideoInspectorControls::class.java.declaredMethods;val grade=VideoGradeControls::class.java.declaredMethods;assertTrue(title.any{it.name=="title"&&it.parameterCount==3&&it.returnType==java.lang.Void.TYPE});assertTrue(title.any{it.name=="format"&&it.parameterCount==3&&it.returnType==java.lang.Void.TYPE});assertTrue(title.any{it.name=="createFormat"&&it.parameterCount==4&&it.returnType==AlertDialog::class.java});assertTrue(title.any{it.name=="createTitle"&&it.parameterCount==4&&it.returnType==AlertDialog::class.java});assertTrue(grade.any{it.name=="show"&&it.parameterCount==4&&it.returnType==java.lang.Void.TYPE});assertTrue(grade.any{it.name=="show\$default"});assertTrue(grade.any{it.name=="create"&&it.parameterCount==5&&it.returnType==AlertDialog::class.java})}
 @Test fun customTitleSizeAndPreciseGradeSurviveExistingChoicesAndCodec(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val clip=p.segments[0];assertEquals(listOf(.035f,.055f,.08f,.061f),VideoTitleSizeChoices.values(clip.titleStyle));val draft=VideoDraft(5000,p.segments,0,0,0,5000,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(draft,restored);assertEquals(.061f,restored.segments[0].titleStyle.size);assertEquals(.123f,restored.segments[0].grade.exposure);assertFalse(p.canUndo)}
 @Test fun earlyFactoryApprovalPredicateRequiresExactTrackedVisibleDialog(){val a=inspectorActivity();val d=editor(a);val r=capture(a);assertEquals(true,call(a,"canUseInspectorReview",d,r));set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertEquals(false,call(a,"canUseInspectorReview",d,r));set(a,"captionReviewDialogs",linkedSetOf(d));showing(d,false);assertEquals(false,call(a,"canUseInspectorReview",d,r));showing(d,true);set(a,"inspectorReviewDialog",dialog());assertEquals(false,call(a,"canUseInspectorReview",d,r))}
 @Test fun outputFormatChangesOnlyRatioAndCropAcrossEveryClipWithOneUndo(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val first=p.segments[0];p.restore(listOf(first.copy(layout=VideoLayout(rotation=90,mirrorX=true)),first.copy(startMs=1000,endMs=4000,speed=2f,title="Other",layout=VideoLayout(1,false,270,false,true))),soundtrack=p.soundtrack);val old=p.segments;val music=p.soundtrack;val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r){p.setFormat(2,true)});assertEquals(old.map{it.copy(layout=it.layout.copy(ratio=2,crop=true))},p.segments);assertSame(music,p.soundtrack);assertEquals(VideoPlaybackTime.durationUs(old),VideoPlaybackTime.durationUs(p.segments));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertTrue(p.segments.all{it.layout.ratio==2&&it.layout.crop})}
 @Test fun outputFormatAndPerClipTransformsSurviveExistingCodec(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;p.restore(p.segments.map{it.copy(layout=VideoLayout(rotation=90,mirrorX=true))},soundtrack=p.soundtrack);val r=capture(a);val d=editor(a);assertTrue(commit(a,d,r){p.setFormat(4,false)});val draft=VideoDraft(5000,p.segments,0,0,0,5000,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(draft,restored);assertEquals(VideoLayout(4,false,90,true,false),restored.segments[0].layout)}
 @Test fun invalidOutputRatioCannotChangeHistoryBeforeCorrectedApply(){val a=inspectorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=editor(a);try{commit(a,d,r){p.setFormat(5,true)};fail("Accepted invalid ratio")}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(e.cause is IllegalArgumentException)};assertSame(old,p.segments);assertFalse(p.canUndo);assertSame(d,get(a,"inspectorReviewDialog"));assertTrue(commit(a,d,r){p.setFormat(4,true)});assertNull(get(a,"inspectorReviewDialog"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo)}
}
